window.products.push({"id":702780,"name":"Silk Road Bazaar Yurt Felt Ornament, 1 EA","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/71u4m7zAb9L._AC_SL1201_.jpg","description":"Silk road bazaar ornaments are made from locally-resourced sheep's wool using traditional felting techniques. Each ornament is uniquely hand-stitched and handcrafted. Silk road bazaar ornaments are made only from natural fibers and are a must have for ornament lovers. Silk road bazaar ornaments are crafted by women-led cooperatives in villages of Kyrgyzstan. Your purchase is helping to empower the women and communities where made.","images":["https://m.media-amazon.com/images/I/71u4m7zAb9L._AC_SL1201_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Silk Road Bazaar","source_asin":"B00IQ72TRQ","category_path":"Home & Kitchen"},"sku":"BM-702780","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B00IQ72TRQ","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B00IQ72TRQ","price_pending":true,"merchant_ready":false});
